public static String convertDatesToWeekdays(String date) {
    // Split the date string into month, day, and year
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    // Create a Calendar object with the given date
    Calendar cal = Calendar.getInstance();
    cal.set(Calendar.MONTH, month - 1);
    cal.set(Calendar.DAY_OF_MONTH, day);
    cal.set(Calendar.YEAR, year);

    // Get the day of the week from the Calendar object
    int dayOfWeek = cal.get(Calendar.DAY_OF_WEEK);

    // Convert the day of the week to a String
    String weekday;
    switch (dayOfWeek) {
        case Calendar.SUNDAY:
            weekday = "Sunday";
            break;
        case Calendar.MONDAY:
            weekday = "Monday";
            break;
        case Calendar.TUESDAY:
            weekday = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekday = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
        default:
            weekday = "Invalid date";
            break;
    }

    // Return the weekday in the format "Month day, year is a weekday"
    return String.format("%s %d, %d is a %s", month, day, year, weekday);
}
