    int nextSmallest = Integer.MAX_VALUE;
    int nextSmallestIndex = startIndex;
    for (int i = startIndex; i < s.length(); i++) {
        if (s.charAt(i) < nextSmallest && s.charAt(i) >= s.charAt(smallestIndex)) {
            nextSmallest = s.charAt(i);
