private static int depthFirstSearch(int[][] mat, int i, int j, int[] previousLine, boolean[][] visited) {
    int currentLength = 1;
    previousLine[j] = 1;

    for (int k = i + 1; k < mat.length; k++) {
        if (mat[k][j] == 1 && !visited[k][j]) {
            currentLength++;
            previousLine[j] = 1;
        } else {
            previousLine[j] = 0;
        }
    }

    for (int k = i - 1; k >= 0; k--) {
        if (mat[k][j] == 1 && !visited[k][j]) {
            currentLength++;
            previousLine[j] = 1;
        } else {
            previousLine[j] = 0;
        }
    }

    return currentLength;
